const name = nameRaw || 'NOA Report';
const slug = name.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');

const entry = {
  section: $json.Section || 'GEOINT',
  tool: $json.Tool,
  input: $json.Input,
  result: $json.Risultati,
  time: new Date().toISOString()
};

return [{ json: { entry, name, slug, save: !!$json.Save } }];

// entry viene da Prepare Report Item
const entry = $json.entry;
const store = Array.isArray($json.store) ? $json.store : [];

const item = {
  ts: new Date().toISOString(),
  section: entry.section,  // es. GEOINT / WEBINT ecc. se lo stai passando
