// --------- Util ---------
const name = $json.name || 'Report';
const slug = $json.slug || 'report';
const store = Array.isArray($json.store) ? $json.store : [];

function fmtUTC(d = new Date()) {
  const iso = new Date(d).toISOString();
  return iso.replace('T', ' ').replace('Z', ' UTC').split('.')[0];
}

//Palette sezione (coppie gradiente)
const palette = {
  WEBINT: ['#1fcc7a', '#17a95f'],
  SOCMINT: ['#ff6b6b', '#e14959'],
  IMINT:  ['#ff9a44', '#ff6a00'],  // aggiornato: arancione
  GEOINT: ['#2d8cff', '#1b6fe6'],
  HUMINT: ['#ffd33d', '#f0b90b'],
  'API KEY': ['#cfd6dd', '#e6ebf0'], // aggiornato: grigio chiaro
};

//schiarisci un HEX (0–100)
function lighten(hex, pct = 28) {
  const m = hex.replace('#', '');
  const n = m.length === 3 ? m.split('').map(x => x + x).join('') : m;
  const r = parseInt(n.slice(0,2),16), g = parseInt(n.slice(2,4),16), b = parseInt(n.slice(4,6),16);
  const mix = c => Math.round(c + (255 - c) * (pct/100));
  const toHex = v => v.toString(16).padStart(2,'0');
  return `#${toHex(mix(r))}${toHex(mix(g))}${toHex(mix(b))}`;
}

//raggruppo per sezione (in ordine di comparsa)
const bySection = {};
const sectionsOrder = [];
for (const e of store) {
  const sec = e.section || 'ALTRO';
  if (!bySection[sec]) { bySection[sec] = []; sectionsOrder.push(sec); }
  if (!e.time) e.time = new Date();
  bySection[sec].push(e);
}

// --------- Render helpers ---------
function esc(s){
  return String(s)
    .replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
}
function renderScalar(v){
  return `<span class="scalar">${esc(v)}</span>`;
}
function renderValue(v, depth = 0, labelForArray = '') {
  if (v === null || v === undefined) return '<span class="null">–</span>';
  const t = typeof v;
  if (t === 'string' || t === 'number' || t === 'boolean') return renderScalar(v);

  //Array
  if (Array.isArray(v)) {
    if (!v.length) return '<span class="empty">[]</span>';
    const items = v.map((item, i) => `
      <details class="box" ${depth < 2 ? 'open' : ''}>
        <summary><span class="caret"></span>${labelForArray ? esc(labelForArray) + ' ' : ''}[${i+1}]</summary>
        <div class="box-inner">
          ${renderValue(item, depth+1)}
        </div>
      </details>
    `).join('');
    return `
      <details class="box" ${depth < 1 ? 'open' : ''}>
        <summary><span class="caret"></span>${labelForArray ? esc(labelForArray) + ' ' : 'Array '}(${v.length})</summary>
        <div class="box-inner">${items}</div>
      </details>
    `;
  }

  //Oggetto
  const entries = Object.entries(v);
  if (!entries.length) return '<span class="empty">{}</span>';
  const rows = entries.map(([k,val]) => {
    const valueHTML = Array.isArray(val)
      ? renderValue(val, depth+1, k)
      : renderValue(val, depth+1);
    return `
      <tr>
        <td class="k">${esc(k)}</td>
        <td class="v">${valueHTML}</td>
      </tr>
    `;
  }).join('');
  return `<table class="kv nest">${rows}</table>`;
}

function chipIndexHTML(sec) {
  const colors = palette[sec] || ['#2f2f2f', '#1a1a1a'];
  return `<a class="chip" href="#sec-${esc(sec)}" style="--c1:${colors[0]};--c2:${colors[1]}">${esc(sec)}</a>`;
}

function sectionHTML(sec, entries, theme='dark') {
  const [c1, c2] = palette[sec] || ['#2f2f2f', '#1a1a1a'];
  const c1soft = lighten(c1, 28), c2soft = lighten(c2, 28);
  return `
<section class="section" id="sec-${esc(sec)}">
  <h2 class="section-title" style="--c1:${c1};--c2:${c2}"><span class="dot"></span>${esc(sec)}</h2>
  ${entries.map(e => `
    <article class="card">
      <div class="row head">
        <div class="k">Tool</div>
        <div class="v tool"><span class="pill" style="--p1:${c1soft};--p2:${c2soft}">${esc(e.tool || '—')}</span></div>
      </div>
      <div class="row">
        <div class="k">Date</div>
        <div class="v">${e.time ? renderScalar(fmtUTC(e.time)) : '<span class="muted">—</span>'}</div>
      </div>
      <div class="row">
        <div class="k">Input</div>
        <div class="v">${renderValue(e.input)}</div>
      </div>
      <div class="row">
        <div class="k">Risultato</div>
        <div class="v">${renderValue(e.result)}</div>
      </div>
    </article>
  `).join('')}
</section>`;
}

