function esc(s){
  return String(s)
    .replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
}
function renderScalar(v){
  return `<span class="scalar">${esc(v)}</span>`;
}
function renderValue(v, depth = 0, labelForArray = '') {
  if (v === null || v === undefined) return '<span class="null">–</span>';
  const t = typeof v;
  if (t === 'string' || t === 'number' || t === 'boolean') return renderScalar(v);

  //Array
  if (Array.isArray(v)) {
    if (!v.length) return '<span class="empty">[]</span>';
    const items = v.map((item, i) => `
      <details class="box" ${depth < 2 ? 'open' : ''}>
        <summary><span class="caret"></span>${labelForArray ? esc(labelForArray) + ' ' : ''}[${i+1}]</summary>
